import torch
from torch import nn

@torch.jit.script
class GroupType(object):
    def __init__(self):
        self.WORLD = 5

group = GroupType()


class TestMod(nn.Module):
    def __init__(self, group):
        super(TestMod, self).__init__()

    def forward(self, input: int):

        if input > 2:
            return group.WORLD + 1
        else:
            return group.WORLD + 5

scripted_mod = torch.jit.script(TestMod(group))
print(scripted_mod.graph)
